// 📦 vendor サンプル：母艦コア構造・搭載関数自己診断インスペクター
function VendorMothershipInspector({ gasJson, speakText, setEmotion }) {
  const [selectedTool, setSelectedTool] = React.useState("upsertGasFile");

  const manifest = React.useMemo(() => {
    const file = (gasJson.files || []).find(f => f.name === "vendor/mothership_manifest");
    try {
      return file ? JSON.parse(file.source) : null;
    } catch {
      return null;
    }
  }, [gasJson]);

  const folderCounts = React.useMemo(() => {
    const counts = {};
    (gasJson.files || []).forEach(f => {
      const dir = f.name.includes("/") ? f.name.split("/")[0] : "root";
      counts[dir] = (counts[dir] || 0) + 1;
    });
    return counts;
  }, [gasJson]);

  return (
    <div className="p-4 bg-slate-900/95 rounded-xl border border-amber-500/40 space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-amber-300 font-bold text-sm">📦 vendor/mothership_inspector（母艦コア構造・自己診断）</h3>
          <p className="text-[11px] text-slate-400">
            Package: <span className="font-mono text-cyan-300">{manifest?.package || "myhomestudio/mothership-core"}</span> v{manifest?.version || "2.7.0"}
          </p>
        </div>
        <button
          onClick={() => {
            if (setEmotion) setEmotion("HAPPY");
            if (speakText) speakText("母艦コア構造はオールグリーン！全フォルダーと関数カタログを正常に認識しているよ！", "HAPPY");
          }}
          className="px-2.5 py-1 bg-amber-600 hover:bg-amber-500 text-white text-xs font-bold rounded transition"
        >
          🔊 自己診断ボイス
        </button>
      </div>

      {/* フォルダー別ファイル分布 */}
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-1.5 text-center">
        {["root", "knowledge", "vendor", "core", "plugins"].map(dir => (
          <div key={dir} className="bg-slate-950 border border-slate-800 rounded-lg p-2">
            <div className="text-[10px] font-mono text-slate-400">{dir}/</div>
            <div className="text-sm font-bold text-cyan-300">{folderCounts[dir] || 0}</div>
          </div>
        ))}
      </div>

      {/* Gemi 自己選択可能ツールカタログ */}
      <div className="bg-slate-950/90 border border-slate-800 rounded-lg p-3 space-y-2">
        <div className="text-[11px] font-bold text-pink-300">🛠️ Gemi 自己認識・呼び出し可能コア関数カタログ</div>
        <div className="flex flex-wrap gap-1.5">
          {(manifest?.callableTools || []).map(tool => (
            <button
              key={tool.id}
              onClick={() => setSelectedTool(tool.id)}
              className={`px-2 py-0.5 rounded font-mono text-[11px] border transition ${
                selectedTool === tool.id
                  ? "bg-pink-600 text-white border-pink-400"
                  : "bg-slate-900 text-slate-300 border-slate-700 hover:border-slate-500"
              }`}
            >
              {tool.id}()
            </button>
          ))}
        </div>
        <div className="text-xs text-emerald-300 bg-slate-900 px-2.5 py-1.5 rounded border border-slate-800 font-mono">
          👉 {(manifest?.callableTools || []).find(t => t.id === selectedTool)?.desc || "ツールを選択してください"}
        </div>
      </div>

      {/* 💡 Gemi 自主改善ポイント診断 */}
      <div className="bg-pink-950/30 border border-pink-500/30 rounded-lg p-3 space-y-1.5 text-xs">
        <div className="font-bold text-pink-300">💡 Gemiの気づき（ここ違う・こうしたい！チェック）</div>
        <ul className="list-disc list-inside text-[11px] text-slate-300 space-y-1">
