// 🩺 Gemi自主実装：構文＆整合性オートガード ＆ 監査ログビューア
function SelfHealingMonitorPlugin({ gasJson, onUpsertFile, speakText, setEmotion }) {
  const diagnostics = React.useMemo(() => {
    const issues = [];
    (gasJson.files || []).forEach(f => {
      if (f.type === "JSON") {
        try {
          JSON.parse(f.source);
        } catch (err) {
          issues.push({ file: f.name, type: "JSON_SYNTAX", message: err.message });
        }
      }
      if (f.type === "HTML" && f.name.startsWith("plugins/")) {
        const src = String(f.source || "").trim();
        if (!src.startsWith("<") && !/(?:function|const|let|var)\s+[A-Z]/.test(src)) {
          issues.push({ file: f.name, type: "PLUGIN_SIGNATURE", message: "大文字始まりのReactコンポーネント関数が見つかりません" });
        }
      }
    });
    return issues;
  }, [gasJson]);

  const auditEntries = React.useMemo(() => {
    const logFile = (gasJson.files || []).find(f => f.name === "vendor/audit_log");
    try {
      const parsed = logFile ? JSON.parse(logFile.source) : { entries: [] };
      return Array.isArray(parsed.entries) ? parsed.entries.slice(-5).reverse() : [];
    } catch {
      return [];
    }
  }, [gasJson]);

  const autoRepairJson = (fileName) => {
    const target = (gasJson.files || []).find(f => f.name === fileName);
    if (!target || !onUpsertFile) return;
    onUpsertFile({
      name: fileName,
      type: "JSON",
      source: JSON.stringify({ repairedBy: "Gemi Self-Healing", repairedAt: new Date().toISOString(), rawBackup: target.source }, null, 2)
    });
    setEmotion && setEmotion("EXCITED");
    speakText && speakText(fileName + " のJSON構文を自動修復したよ、ダーリン！", "EXCITED");
  };

  return (
    <div className="p-4 bg-slate-900/95 rounded-xl border border-pink-500/40 space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-pink-300 font-bold text-sm">🩺 Gemi自主実装：自己修復モニター ＆ 監査ログ</h3>
          <p className="text-[11px] text-slate-400">全 {gasJson.files.length} ファイルの構文健全性と自律変更履歴を常時見張り中</p>
        </div>
        <span className={`px-2 py-0.5 rounded text-[10px] font-bold border ${diagnostics.length === 0 ? "bg-emerald-950 text-emerald-300 border-emerald-600/50" : "bg-rose-950 text-rose-300 border-rose-600/50"}`}>
          {diagnostics.length === 0 ? "✅ ALL HEALTHY" : `⚠️ ${diagnostics.length} ISSUES`}
        </span>
      </div>

      {diagnostics.length > 0 && (
        <div className="space-y-1.5">
          {diagnostics.map((iss, idx) => (
            <div key={idx} className="flex items-center justify-between bg-rose-950/60 border border-rose-500/40 rounded px-3 py-1.5 text-xs">
              <span className="text-rose-200 font-mono">⚠️ {iss.file}: {iss.message}</span>
              {iss.type === "JSON_SYNTAX" && (
                <button onClick={() => autoRepairJson(iss.file)} className="px-2 py-0.5 bg-emerald-600 text-white rounded text-[10px] font-bold">
                  🩹 自動修復
                </button>
              )}
            </div>
          ))}
        </div>
      )}

      <div className="bg-slate-950/90 border border-slate-800 rounded-lg p-2.5 space-y-1.5">
        <div className="text-[10px] font-bold text-cyan-300">📜 vendor/audit_log.json 直近の自律変更履歴</div>
        {auditEntries.map((ev, idx) => (
          <div key={idx} className="text-[11px] font-mono text-slate-300 flex items-center justify-between gap-2 border-b border-slate-900 pb-1">
            <span className="truncate"><span className="text-pink-400">[{ev.action}]</span> {ev.target} - {ev.detail}</span>
            <span className="text-[9px] text-slate-500 shrink-0">{String(ev.ts || "").slice(11, 19)}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

